package com.networkmonitorpro.data.repository; import android.content.*; import androidx.lifecycle.*; import com.networkmonitorpro.data.db.AppDatabase; import com.networkmonitorpro.data.entity.*; import com.networkmonitorpro.network.NetworkSnapshot; import java.io.*; import java.util.*; public class AnalyticsRepository{ private final AppDatabase db; public AnalyticsRepository(Context c){db=AppDatabase.get(c);} public LiveData<List<AnalyticsRecord>> recent(){return db.analyticsDao().recent();} public void record(NetworkSnapshot s){AppExecutors.IO.execute(()->db.analyticsDao().insert(new AnalyticsRecord(s.type,s.signalLevel,s.qualityScore,s.downBps,s.upBps,System.currentTimeMillis())));} public File exportCsv(Context c) throws IOException{File dir=new File(c.getCacheDir(),"exports"); if(!dir.exists())dir.mkdirs(); File f=new File(dir,"network-monitor-export.csv"); try(PrintWriter w=new PrintWriter(new FileWriter(f))){w.println("type,signal,quality,download_bps,upload_bps,timestamp");} return f;} public void cleanup(){long cutoff=System.currentTimeMillis()-1000L*60*60*24*30; AppExecutors.IO.execute(()->{db.analyticsDao().cleanup(cutoff);db.notificationDao().cleanup(cutoff);db.downloadDao().cleanup(cutoff);});} }
